# attempt.schema.json

Generated, complete JSON Schema reference. Required/default/conditional rules are not inferred.

```json
{
  "$id": "https://coding-hermes.local/chd33/schemas/attempt.schema.json",
  "$schema": "https://json-schema.org/draft/2020-12/schema",
  "additionalProperties": false,
  "allOf": [
    {
      "if": {
        "properties": {
          "state": {
            "const": "closed"
          }
        }
      },
      "then": {
        "required": [
          "close_reason",
          "stopped_at"
        ]
      }
    },
    {
      "if": {
        "properties": {
          "close_reason": {
            "const": "waiting_human"
          }
        }
      },
      "then": {
        "properties": {
          "state": {
            "const": "closed"
          }
        }
      }
    }
  ],
  "properties": {
    "attempt": {
      "minimum": 1,
      "type": "integer"
    },
    "attempt_id": {
      "minLength": 1,
      "type": "string"
    },
    "close_reason": {
      "enum": [
        "waiting_human",
        "verified",
        "failed",
        "cancelled",
        "escalated",
        null
      ],
      "type": [
        "string",
        "null"
      ]
    },
    "created_at": {
      "format": "date-time",
      "type": "string"
    },
    "credential_scope": {
      "minLength": 1,
      "type": "string"
    },
    "gateway_request_key": {
      "minLength": 1,
      "type": "string"
    },
    "prior_attempt_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "profile_ref": {
      "minLength": 1,
      "type": "string"
    },
    "record_id": {
      "minLength": 1,
      "type": "string"
    },
    "report_received_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "request_digest": {
      "pattern": "^sha256:[A-Fa-f0-9]{64}$",
      "type": "string"
    },
    "request_ref": {
      "minLength": 1,
      "type": "string"
    },
    "reservation_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "reservation_state": {
      "enum": [
        "held",
        "released"
      ]
    },
    "run_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "run_state": {
      "enum": [
        "not_started",
        "running",
        "stopped",
        "terminal",
        "unknown",
        "unreachable"
      ]
    },
    "schema_version": {
      "const": 1
    },
    "send_id": {
      "minLength": 1,
      "type": "string"
    },
    "state": {
      "enum": [
        "open",
        "waiting",
        "paused:uncertain",
        "paused:unreachable",
        "closed"
      ]
    },
    "stop_proof_ref": {
      "type": [
        "string",
        "null"
      ]
    },
    "stopped_at": {
      "format": "date-time",
      "type": [
        "string",
        "null"
      ]
    },
    "successor_attempt_id": {
      "type": [
        "string",
        "null"
      ]
    },
    "target": {
      "additionalProperties": false,
      "properties": {
        "agent_id": {
          "type": "string"
        },
        "gateway_id": {
          "type": "string"
        },
        "profile_ref": {
          "type": "string"
        },
        "room_id": {
          "type": "string"
        },
        "session_allocation_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "session_id": {
          "type": [
            "string",
            "null"
          ]
        },
        "thread_root": {
          "type": [
            "integer",
            "null"
          ]
        },
        "work_uid": {
          "type": [
            "string",
            "null"
          ]
        }
      },
      "required": [
